  it('toggles by index, skipping fenced code', () => {
    expect(toggleCheckbox(src, 0).split('\n')[0]).toBe('- [x] a')
    expect(toggleCheckbox(src, 1).split('\n')[1]).toBe('- [ ] b')
    expect(toggleCheckbox(src, 2).split('\n')[8]).toBe('1. [x] c')
