@import "tailwindcss";

@custom-variant dark (&:where(.dark, .dark *));

:root {
  color-scheme: light;
}
.dark {
  color-scheme: dark;
}

html,
body,
#root {
  height: 100%;
}
body {
  background: #f8fafc;
  color: #0f172a;
}
.dark body {
  background: #0b1120;
  color: #e2e8f0;
}

mark {
  background: #fde047;
  color: #111827;
  border-radius: 2px;
  padding: 0 1px;
}

.md {
  line-height: 1.65;
  overflow-wrap: anywhere;
}
.md > :first-child { margin-top: 0; }
.md h1 { font-size: 1.75rem; font-weight: 700; margin: 1.2em 0 0.5em; }
.md h2 { font-size: 1.4rem; font-weight: 700; margin: 1.2em 0 0.5em; }
.md h3 { font-size: 1.15rem; font-weight: 600; margin: 1.1em 0 0.4em; }
.md h4, .md h5, .md h6 { font-weight: 600; margin: 1em 0 0.4em; }
.md p { margin: 0.7em 0; }
.md ul { list-style: disc; padding-left: 1.5rem; margin: 0.7em 0; }
.md ol { list-style: decimal; padding-left: 1.5rem; margin: 0.7em 0; }
.md li > ul, .md li > ol { margin: 0.2em 0; }
.md li:has(> input[type="checkbox"]) { list-style: none; margin-left: -1.25rem; }
.md input[type="checkbox"] { width: 1rem; height: 1rem; margin-right: 0.35rem; vertical-align: -2px; cursor: pointer; accent-color: #4f46e5; }
.md a { color: #4f46e5; text-decoration: underline; }
.dark .md a { color: #a5b4fc; }
.md code { font-family: ui-monospace, Menlo, Consolas, monospace; font-size: 0.9em; background: rgba(100,116,139,0.18); padding: 0.1em 0.35em; border-radius: 4px; }
.md pre { background: #0f172a; color: #e2e8f0; padding: 0.9rem 1rem; border-radius: 8px; overflow-x: auto; margin: 0.9em 0; }
.md pre code { background: none; padding: 0; color: inherit; }
.md blockquote { border-left: 4px solid #94a3b8; padding-left: 1rem; color: #64748b; margin: 0.8em 0; }
.md hr { border: 0; border-top: 1px solid #cbd5e1; margin: 1.2em 0; }
.dark .md hr { border-color: #334155; }
.md table { border-collapse: collapse; margin: 0.8em 0; }
.md th, .md td { border: 1px solid #cbd5e1; padding: 0.3rem 0.6rem; }
.dark .md th, .dark .md td { border-color: #334155; }

